from harvests import Harvest, load_harvests, ROWS
from search import harvests_for, has_field

KEY = ROWS[0][0]
COUNT = sum(1 for k, _ in ROWS if k == KEY)


def test_upper_case_with_spaces():
    assert len(harvests_for(list(load_harvests()), " " + KEY.upper() + " ")) == COUNT


def test_stored_value_not_tidy():
    data = [Harvest("  Alpha", 1), Harvest("beta", 2), Harvest("ALPHA ", 3)]
    assert [x.kilos for x in harvests_for(data, "alpha")] == [1, 3]


def test_exact():
    assert len(harvests_for(list(load_harvests()), KEY)) == COUNT


def test_no_match():
    assert harvests_for(list(load_harvests()), "zzz") == [] and not has_field(list(load_harvests()), "zzz")
